<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class Booking extends Model { protected $fillable=['reference','customer_id','vehicle_id','pickup_location_id','dropoff_location_id','pickup_location_text','dropoff_location_text','pickup_at','return_at','handover_at','actual_return_at','handover_odometer','return_odometer','assigned_to','rental_type','duration_days','base_price','additional_charges','discount','total_price','deposit','payment_status','status','customer_notes','admin_notes']; protected function casts():array{return ['pickup_at'=>'datetime','return_at'=>'datetime','handover_at'=>'datetime','actual_return_at'=>'datetime','base_price'=>'decimal:2','additional_charges'=>'decimal:2','discount'=>'decimal:2','total_price'=>'decimal:2','deposit'=>'decimal:2'];} public function customer(){return $this->belongsTo(Customer::class);} public function vehicle(){return $this->belongsTo(Vehicle::class);} public function pickupLocation(){return $this->belongsTo(Location::class,'pickup_location_id');} public function dropoffLocation(){return $this->belongsTo(Location::class,'dropoff_location_id');} public function assignee(){return $this->belongsTo(User::class,'assigned_to');} public function statusHistory(){return $this->hasMany(BookingStatusHistory::class)->orderBy('created_at');} public function inspections(){return $this->hasMany(VehicleInspection::class);} }
